import Foundation
import XCTest

/// Verifies the OpenAPI document backing the generated API client.
///
/// The typed client for `/api/v1` is generated by `swift-openapi-generator`
/// from a vendored copy of the spec published by `viamin/color_matching` at
/// `GET /api/v1/openapi.json` (introduced in viamin/color_matching#113). The
/// document must live at `iOS/OpenAPI/color-matching-openapi.json` so the
/// generation plugin can consume it and so server-side drift shows up as a
/// regeneration diff.
///
/// These tests fail while the document is not vendored yet; they are the
/// compile-safe gate for the "fetch or vendor the OpenAPI document"
/// deliverable of the generated-client migration.
final class OpenAPISpecCoverageTests: XCTestCase {
    private static let specURL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent() // ColorMatchingLPSAppTests
        .deletingLastPathComponent() // Tests
        .deletingLastPathComponent() // iOS
        .appendingPathComponent("OpenAPI")
        .appendingPathComponent("color-matching-openapi.json")

    func testVendoredOpenAPIDocumentExistsAtContractLocation() throws {
        let url = Self.specURL
        XCTAssertTrue(
            FileManager.default.fileExists(atPath: url.path),
            "Missing vendored OpenAPI document at \(url.path). Vendor the spec served by "
                + "viamin/color_matching at GET /api/v1/openapi.json so the generated client "
                + "and this suite share one machine-readable contract."
        )
        let data = try Data(contentsOf: url)
        XCTAssertFalse(data.isEmpty)
    }

    func testVendoredSpecIsOpenAPI3WithBearerAuthScheme() throws {
        let spec = try loadSpecDocument()
        let version = try XCTUnwrap(spec["openapi"] as? String, "missing top-level `openapi` version")
        XCTAssertTrue(version.hasPrefix("3."), "expected an OpenAPI 3.x document, got \(version)")
        XCTAssertNotNil(spec["info"], "missing top-level `info` section")
        XCTAssertNotNil(spec["paths"], "missing top-level `paths` section")

        let schemes = try XCTUnwrap(
            (spec["components"] as? [String: Any])?["securitySchemes"] as? [String: Any],
            "missing components.securitySchemes"
        )
        let bearer = try XCTUnwrap(schemes["bearerAuth"] as? [String: Any], "missing bearerAuth security scheme")
        XCTAssertEqual(bearer["type"] as? String, "http")
        XCTAssertEqual(bearer["scheme"] as? String, "bearer")
    }

    func testVendoredSpecCoversEverySurfaceUsedByTheApp() throws {
        let paths = try loadSpecDocument().paths
        let expectedOperations = [
            "/api/v1/test_sheets/{sheet_id}/manifest": "get",
            "/api/v1/test_sheets/recent": "get",
            "/api/v1/test_sheets/{sheet_id}/ranked_results": "get",
            "/api/v1/test_sheets/{sheet_id}/captures": "post",
            "/api/v1/captures/{capture_id}/measurements": "post",
            "/api/v1/captures/{capture_id}/judgments": "post",
        ]
        for (path, method) in expectedOperations {
            let item = try XCTUnwrap(paths[path] as? [String: Any], "spec is missing path \(path)")
            XCTAssertNotNil(item[method], "spec path \(path) has no \(method) operation")
        }
    }

    func testVendoredSpecDeclaresSchemasNeededForClientGeneration() throws {
        let schemas = try loadSpecDocument().schemas
        let requiredSchemas = [
            "TestSheetManifest",
            "RecentSheetsResponse",
            "RankedResults",
            "CaptureRequest",
            "CaptureCreatedResponse",
            "MeasurementUploadRequest",
            "MeasurementUploadResponse",
            "JudgmentUploadRequest",
            "JudgmentUploadResponse",
            "ApiErrorResponse",
        ]
        for name in requiredSchemas {
            XCTAssertNotNil(schemas[name], "components.schemas is missing \(name)")
        }
    }

    func testMeasurementUploadSchemaRequiresNormalizedMedianPerPatch() throws {
        let spec = try loadSpecDocument()
        let operation = try spec.operation(method: "post", path: "/api/v1/captures/{capture_id}/measurements")
        let requestBody = try XCTUnwrap(operation["requestBody"] as? [String: Any])
        let schema = try requestBody.jsonSchema(named: "measurement upload")
        let upload = try spec.resolveReference(schema)
        let properties = try XCTUnwrap(upload["properties"] as? [String: Any])
        let measurements = try spec.resolveReference(try XCTUnwrap(properties["measurements"] as? [String: Any]))
        let items = try XCTUnwrap(measurements["items"] as? [String: Any])
        let required = try XCTUnwrap(items["required"] as? [String])
        XCTAssertTrue(
            required.contains("normalized_linear_rgb_median"),
            "published spec requires normalized_linear_rgb_median on every measurement item; got \(required)"
        )
    }

    func testCaptureCreationSchemaAcceptsNestedMetadataVariant() throws {
        let spec = try loadSpecDocument()
        let operation = try spec.operation(method: "post", path: "/api/v1/test_sheets/{sheet_id}/captures")
        let requestBody = try XCTUnwrap(operation["requestBody"] as? [String: Any])
        let schema = try requestBody.jsonSchema(named: "capture creation")
        let captureRequest = try spec.resolveReference(schema)
        let properties = try XCTUnwrap(captureRequest["properties"] as? [String: Any])
        XCTAssertNotNil(properties["metadata"], "CaptureRequest must keep the nested `metadata` variant the app uploads")
        XCTAssertNotNil(properties["quality"], "CaptureRequest must keep the nested `quality` block the app uploads")
    }

    func testRankedResultsOperationReturnsRankedResultsSchema() throws {
        let spec = try loadSpecDocument()
        let operation = try spec.operation(method: "get", path: "/api/v1/test_sheets/{sheet_id}/ranked_results")
        let responses = try XCTUnwrap(operation["responses"] as? [String: Any])
        let ok = try XCTUnwrap(responses["200"] as? [String: Any], "ranked_results must document a 200 response")
        let schema = try ok.jsonSchema(named: "ranked_results 200 response")
        let ranked = try spec.resolveReference(schema)
        let properties = try XCTUnwrap(ranked["properties"] as? [String: Any])
        XCTAssertNotNil(properties["schema_version"])
        XCTAssertNotNil(properties["sheet_id"])
    }
}

private extension [String: Any] {
    var paths: [String: Any] {
        self["paths"] as? [String: Any] ?? [String: Any]()
    }

    var schemas: [String: Any] {
        let components = self["components"] as? [String: Any] ?? [String: Any]()
        return components["schemas"] as? [String: Any] ?? [String: Any]()
    }

    func operation(method: String, path: String) throws -> [String: Any] {
        let item = try XCTUnwrap(paths[path] as? [String: Any], "spec is missing path \(path)")
        return try XCTUnwrap(item[method] as? [String: Any], "spec path \(path) has no \(method) operation")
    }

    func jsonSchema(named label: String) throws -> [String: Any] {
        let content = try XCTUnwrap(self["content"] as? [String: Any], "\(label) request body has no content map")
        let json = try XCTUnwrap(content["application/json"] as? [String: Any], "\(label) body is not application/json")
        return try XCTUnwrap(json["schema"] as? [String: Any], "\(label) body has no schema")
    }

    func resolveReference(_ node: [String: Any]) throws -> [String: Any] {
        guard let ref = node["$ref"] as? String else { return node }
        let prefix = "#/components/schemas/"
        XCTAssertTrue(ref.hasPrefix(prefix), "unsupported $ref \(ref)")
        let name = String(ref.dropFirst(prefix.count))
        return try XCTUnwrap(schemas[name] as? [String: Any], "unresolvable $ref \(ref)")
    }
}
